CREATE DATABASE IF NOT EXISTS chinalanding CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE chinalanding;
CREATE TABLE admins (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, last_login_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE categories (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, slug VARCHAR(120) NOT NULL UNIQUE, description TEXT NOT NULL, seo_title VARCHAR(255) NOT NULL, meta_description VARCHAR(255) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE articles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(255) NOT NULL, slug VARCHAR(180) NOT NULL UNIQUE, seo_title VARCHAR(255) NOT NULL, meta_description VARCHAR(255) NOT NULL, content_html LONGTEXT NOT NULL, status ENUM('draft','published') NOT NULL DEFAULT 'draft', published_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(status), INDEX(published_at)) ENGINE=InnoDB;
CREATE TABLE article_category (article_id BIGINT UNSIGNED NOT NULL, category_id INT UNSIGNED NOT NULL, PRIMARY KEY(article_id,category_id), FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE CASCADE, FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE tags (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, slug VARCHAR(80) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE article_tags (article_id BIGINT UNSIGNED NOT NULL, tag_id INT UNSIGNED NOT NULL, PRIMARY KEY(article_id,tag_id), FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE CASCADE, FOREIGN KEY(tag_id) REFERENCES tags(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE settings (`key` VARCHAR(120) PRIMARY KEY, `value` TEXT NOT NULL) ENGINE=InnoDB;
CREATE TABLE redirects (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, from_path VARCHAR(255) NOT NULL UNIQUE, to_path VARCHAR(255) NOT NULL, status_code SMALLINT NOT NULL DEFAULT 301) ENGINE=InnoDB;
CREATE TABLE media (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, filename VARCHAR(255) NOT NULL, mime_type VARCHAR(100) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE seo_metadata (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, entity_type VARCHAR(40) NOT NULL, entity_id BIGINT UNSIGNED NOT NULL, canonical_url VARCHAR(500) NULL, og_image VARCHAR(500) NULL, UNIQUE KEY entity(entity_type,entity_id)) ENGINE=InnoDB;
